450	// resolveAgentType picks the best agent type from the context and existing state.
451	// Priority: existing state > context value.
452	func resolveAgentType(ctxAgentType types.AgentType, state *SessionState) types.AgentType {
453		if state != nil && state.AgentType != "" {
454			return state.AgentType
455		}
456		return ctxAgentType
457	}
458	
459	// EnsurePrimaryRef creates or updates the local primary metadata ref.
460	//
461	// A configured checkpoint_remote is the authoritative checkpoint store: when one
462	// is set the local ref is only ever sourced from it, never from a (possibly
463	// stale) tracking ref (issue #1374). Without a checkpoint_remote, the elected
464	// checkpoint sync remote holds the store — when Primary is in Push and the
465	// local ref is missing or un-initialized, the local ref is created/updated
466	// from the ELECTED remote's tracking ref only; the legacy origin read tier
467	// never seeds or advances local refs. Otherwise an empty orphan is created.
468	// primaryIsGitRefs reports whether the configured primary checkpoint backend is
469	// git-refs. Resolution is fail-soft: any config-load error is treated as the
470	// default git-branch backend (returns false), preserving legacy behavior.
471	func primaryIsGitRefs(ctx context.Context) bool {
472		cfg, err := settings.LoadCheckpointsConfig(ctx)
473		if err != nil {
474			return false
475		}
476		return checkpoint.PrimaryIsRefs(cfg)
477	}
478	
479	func EnsurePrimaryRef(ctx context.Context, repo *git.Repository) error {
480		// Rebind settings/remote resolution to the repository being modified rather
481		// than the ambient working directory, so the "is a checkpoint_remote
482		// configured" decision (and any fetch below) targets repo even when a caller
483		// passes a handle for a repo that is not CWD. EnsureSetup opens repo from CWD
484		// and tests t.Chdir into it, so in normal use this is a no-op.
485		if root, rootErr := getRepoPath(repo); rootErr == nil {
486			ctx = settings.WithWorktreeRoot(ctx, root)
487		}
488	
489		refs := checkpoint.ResolveRefs(ctx)
490		primaryName := refs.Primary.Short()
491	
492		// Under the git-refs primary backend, checkpoints are written to
493		// per-checkpoint refs and nothing is ever written to the v1 metadata
494		// branch. Seeding an empty orphan v1 here would leave a vestigial,
495		// never-written branch — the surprise a user hit when `entire enable`
496		// selected git-refs yet still created entire/checkpoints/v1. We still adopt
497		// real v1 data that already exists on origin or a checkpoint_remote below
498		// (so legacy checkpoints stay readable); we only suppress the empty-orphan
499		// fallback. Resolution is fail-soft: an unreadable config keeps the legacy
500		// git-branch seeding behavior.
501		skipEmptyOrphan := primaryIsGitRefs(ctx)
502	
503		localRef, localErr := repo.Reference(refs.Primary, true)
504		if localErr != nil && !errors.Is(localErr, plumbing.ErrReferenceNotFound) {
505			return fmt.Errorf("failed to check metadata ref: %w", localErr)
506		}
507		localExists := localErr == nil
508	
509		// A configured checkpoint_remote is the authoritative checkpoint store and
510		// takes precedence over origin's (possibly stale) primary tracking ref. When
511		// it is configured we never seed from origin: a machine migrated from
512		// origin-hosted checkpoints to a dedicated checkpoint_remote must not replay
513		// origin's stale checkpoints into it (issue #1374). The network fetch is
514		// additionally gated on an explicit enable flow (WithCheckpointRemoteBootstrap):
515		// the per-turn hook hot path stays network-free and self-heals via the
516		// empty-orphan fallback.
517		if remote.Configured(ctx) {
518			if localExists {
519				// Heal an un-initialized orphan (empty, or vercel.json-only on a
520				// vercel-enabled repo) from the checkpoint remote. Whatever the
521				// outcome, never fall through to origin.
522				healed, err := healPrimaryFromCheckpointRemote(ctx, repo, localRef, refs.Primary)
523				if err != nil {
524					return err
525				}
526				if healed {
527					fmt.Fprintf(os.Stderr, "✓ Updated local ref '%s' from checkpoint remote\n", primaryName)
528				}
529				return nil
530			}
531			// Local ref missing — fetch the real branch before creating a fresh
532			// orphan: an orphan would diverge from it, hide existing checkpoints, and
533			// be rejected non-fast-forward on later syncs.
534			if bootstrapPrimaryFromCheckpointRemote(ctx, repo, refs.Primary) {
535				fmt.Fprintf(os.Stderr, "✓ Created local ref '%s' from checkpoint remote\n", primaryName)
536				return nil
537			}
538			// Nothing usable on the checkpoint remote (fetch skipped/failed or the
539			// remote has no data) — create a fresh orphan that future pushes publish
540			// there. Still never origin.
541			if skipEmptyOrphan {
542				return nil
543			}
544			return createOrphanMetadataRef(ctx, repo, refs)
545		}
546	
547		// No checkpoint_remote configured — the elected checkpoint sync remote
548		// holds the checkpoint store. Local-ref seeding and healing are confined
549		// to that elected remote: the legacy origin read tier is strictly
550		// read-only, so a stale refs/remotes/origin/... tracking ref must never
551		// seed or update the local primary when the election points elsewhere or
552		// failed (a stale origin driving local-ref writes is the #1374-class
553		// hazard). When the elected remote's tracking ref is unavailable there is
