12		"github.com/entireio/cli/cmd/entire/cli/gitrepo"
13		"github.com/entireio/cli/cmd/entire/cli/logging"
14		"github.com/entireio/cli/cmd/entire/cli/settings"
15	
16		"github.com/go-git/go-git/v6"
17	)
18	
19	const originRemote = "origin"
20	
21	const (
22		ProtocolSSH    = gitremote.ProtocolSSH
23		ProtocolHTTPS  = gitremote.ProtocolHTTPS
24		ProtocolEntire = gitremote.ProtocolEntire
25	)
26	
27	// Info is an alias for gitremote.Info.
28	type Info = gitremote.Info
29	
30	// FetchURLOptions configures FetchURL.
31	type FetchURLOptions struct {
32		WorktreeRoot string
33	
34		// LeadReadRemote is the checkpoint read candidate the caller wants the
35		// fetch URL derived from (the elected sync remote, or one entry of the
36		// read-candidate chain while iterating it), supplied by cli/strategy
37		// callers — this package cannot resolve the election itself. When set and
38		// NO checkpoint_remote is configured, the base fetch URL is derived from
39		// it instead of unconditionally from origin. The dedicated
40		// checkpoint_remote derivation path ignores it entirely.
41		LeadReadRemote string
42	}
43	
44	// FetchURL returns the effective checkpoint fetch URL for the current repository.
45	// If strategy_options.checkpoint_remote is configured, the returned URL is derived
46	// from the origin remote's protocol/host and the configured checkpoint repo.
47	// Otherwise, the origin remote URL is returned directly.
48	//
49	// If ENTIRE_CHECKPOINT_TOKEN is set and a checkpoint remote is configured, HTTPS is
50	// forced so the token can be used even when origin is configured via SSH.
51	func FetchURL(ctx context.Context, opts ...FetchURLOptions) (string, error) {
52		url, _, err := fetchURLAuthoritative(ctx, opts...)
53		return url, err
54	}
55	
56	// fetchURLAuthoritative is FetchURL plus whether the returned URL is
57	// authoritative for checkpoint refs. It is false exactly when a
58	// checkpoint_remote IS configured (or cannot be determined) but resolution
59	// fell back to the origin URL — a remote that by construction does not host
60	// the configured checkpoint refs. Callers that classify "ref absent on the
61	// remote" (FetchCheckpointRef's ls-remote probe) must not treat emptiness on
62	// a non-authoritative target as absence.
63	func fetchURLAuthoritative(ctx context.Context, opts ...FetchURLOptions) (string, bool, error) {
64		var opt FetchURLOptions
65		if len(opts) > 0 {
66			opt = opts[0]
67		}
68	
69		getRemoteURL := GetRemoteURL
70		if opt.WorktreeRoot != "" {
71			ctx = settings.WithWorktreeRoot(ctx, opt.WorktreeRoot)
72			getRemoteURL = func(ctx context.Context, remoteName string) (string, error) {
73				return GetRemoteURLInDir(ctx, opt.WorktreeRoot, remoteName)
74			}
75		}
76	
77		withToken := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != ""
78	
79		originURL, originErr := getRemoteURL(ctx, originRemote)
80		if originErr != nil {
81			originURL = ""
82		}
83	
84		if originURL != "" && withToken {
85			if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
86				originURL = tokenURL
87			}
88		}
89	
90		s, err := settings.Load(ctx)
91		if err != nil {
92			if originURL != "" {
93				logFallback(ctx, "fetch", originURL, "load settings", err)
94				// Settings unreadable → checkpoint_remote unknown; conservative:
95				// do not certify origin as authoritative for checkpoint refs.
96				return originURL, false, nil
97			}
98			return "", false, fmt.Errorf("load settings: %w", err)
99		}
100	
